          id: String(derivedTask.id || parent.id || ""),
          path: location.path,
          task: derivedTask,
          source: "derived-note",
          sourceKind: "note-task-reference-row",
          sourceId,
          children: [],
          parentRecord: null,
          rootRecord: null,
          treeDepth: 0,
          treePath: [],
          siblingOrder: null,
          hierarchyIssue: ""
